import { useRef, useEffect } from "react"
import { EditorContent, useEditor } from "@tiptap/react"
import StarterKit from "@tiptap/starter-kit"
import LinkExt from "@tiptap/extension-link"
import Placeholder from "@tiptap/extension-placeholder"
import { Markdown } from "tiptap-markdown"
import { Table } from "@tiptap/extension-table"
import { TableRow } from "@tiptap/extension-table-row"
import { TableCell } from "@tiptap/extension-table-cell"
import { TableHeader } from "@tiptap/extension-table-header"
import TaskList from "@tiptap/extension-task-list"
import TaskItem from "@tiptap/extension-task-item"
import { EditorToolbar } from "./EditorToolbar"
import { useFileDocument } from "../hooks/useFileDocument"
import { getMarkdown, WikiLink } from "../lib/editor"

export function InlineMarkdownEditor({ path, expanded }: { path: string; expanded: boolean }) {
  const doc = useFileDocument(path)
  const saveTimer = useRef<ReturnType<typeof setTimeout>>(null)
  const settingContent = useRef(false)
  const hasSetContent = useRef(false)

  const editor = useEditor({
    extensions: [
      StarterKit,
      LinkExt.configure({ openOnClick: false }),
      WikiLink,
      Placeholder.configure({ placeholder: "Start writing..." }),
      Markdown,
      Table.configure({ resizable: false }),
      TableRow,
      TableCell,
      TableHeader,
      TaskList,
      TaskItem.configure({ nested: true }),
    ],
    content: "",
    onUpdate: ({ editor }) => {
      if (!hasSetContent.current || settingContent.current) return
      doc.setContent(getMarkdown(editor))
      if (saveTimer.current) clearTimeout(saveTimer.current)
      saveTimer.current = setTimeout(() => doc.save(), 1500)
    },
  })

  useEffect(() => {
    if (editor && doc.loaded && !hasSetContent.current) {
      hasSetContent.current = true
      if (doc.content) {
        settingContent.current = true
        editor.commands.setContent(doc.content)
        settingContent.current = false
      }
    }
  }, [editor, doc.loaded, doc.content])

  const prevContent = useRef("")
  useEffect(() => {
    if (!editor || !hasSetContent.current) return
    if (doc.content === prevContent.current) return
    prevContent.current = doc.content
    const currentMd = getMarkdown(editor)
    if (currentMd !== doc.content) {
      settingContent.current = true
      editor.commands.setContent(doc.content)
      settingContent.current = false
    }
  }, [doc.content, editor])

  useEffect(() => {
    return () => {
      if (saveTimer.current) clearTimeout(saveTimer.current)
      if (doc.dirty) doc.save()
    }
  }, [doc])

  if (!expanded) return null

  return (
    <div className="border-t border-border flex flex-col">
      <div className="overflow-y-auto max-h-[60vh] bg-background">
        <div className="prose prose-sm dark:prose-invert prose-p:my-1 prose-ul:my-1 prose-ol:my-1 prose-li:my-0.5 prose-headings:my-2 prose-h1:text-xl prose-h2:text-lg prose-h3:text-base prose-hr:my-3 px-4 py-3 [&_.tiptap]:outline-none [&_.tiptap]:min-h-12">
          <EditorContent editor={editor} />
        </div>
      </div>
      <EditorToolbar editor={editor} />
    </div>
  )
}

import type { Editor } from "@tiptap/react"
import type { Icon } from "@phosphor-icons/react"
import {
  TextHOneIcon,
  TextHTwoIcon,
  TextBolderIcon,
  TextItalicIcon,
  ListBulletsIcon,
  LinkIcon,
  CodeIcon,
  ArrowCounterClockwiseIcon,
  ArrowClockwiseIcon,
} from "@phosphor-icons/react"
import { useEffect, useState } from "react"

type Action = {
  icon: Icon
  label: string
  command: (editor: Editor) => void
  isActive?: (editor: Editor) => boolean
}

const actions: Action[] = [
  {
    icon: TextHOneIcon,
    label: "Heading 1",
    command: e => e.chain().focus().toggleHeading({ level: 1 }).run(),
    isActive: e => e.isActive("heading", { level: 1 }),
  },
  {
    icon: TextHTwoIcon,
    label: "Heading 2",
    command: e => e.chain().focus().toggleHeading({ level: 2 }).run(),
    isActive: e => e.isActive("heading", { level: 2 }),
  },
  {
    icon: TextBolderIcon,
    label: "Bold",
    command: e => e.chain().focus().toggleBold().run(),
    isActive: e => e.isActive("bold"),
  },
  {
    icon: TextItalicIcon,
    label: "Italic",
    command: e => e.chain().focus().toggleItalic().run(),
    isActive: e => e.isActive("italic"),
  },
  {
    icon: ListBulletsIcon,
    label: "Bullet list",
    command: e => e.chain().focus().toggleBulletList().run(),
    isActive: e => e.isActive("bulletList"),
  },
  {
    icon: LinkIcon,
    label: "Link",
    command: e => {
      if (e.isActive("link")) {
        e.chain().focus().unsetLink().run()
      } else {
        const url = window.prompt("URL")
        if (url) e.chain().focus().setLink({ href: url }).run()
      }
    },
    isActive: e => e.isActive("link"),
  },
  {
    icon: CodeIcon,
    label: "Code",
    command: e => e.chain().focus().toggleCode().run(),
    isActive: e => e.isActive("code"),
  },
  {
    icon: ArrowCounterClockwiseIcon,
    label: "Undo",
    command: e => e.chain().focus().undo().run(),
  },
  {
    icon: ArrowClockwiseIcon,
    label: "Redo",
    command: e => e.chain().focus().redo().run(),
  },
]

export function EditorToolbar({ editor }: { editor: Editor | null }) {
  const [, forceUpdate] = useState(0)
  const [bottomOffset, setBottomOffset] = useState(0)

  // Re-render on selection/content changes for active state
  useEffect(() => {
    if (!editor) return
    const update = () => forceUpdate(n => n + 1)
    editor.on("selectionUpdate", update)
    editor.on("transaction", update)
    return () => {
      editor.off("selectionUpdate", update)
      editor.off("transaction", update)
    }
  }, [editor])

  // Position above virtual keyboard on mobile
  useEffect(() => {
    const viewport = window.visualViewport
    if (!viewport) return
    const onResize = () => {
      const offset = window.innerHeight - viewport.height - viewport.offsetTop
      setBottomOffset(Math.max(0, offset))
    }
    viewport.addEventListener("resize", onResize)
    viewport.addEventListener("scroll", onResize)
    return () => {
      viewport.removeEventListener("resize", onResize)
      viewport.removeEventListener("scroll", onResize)
    }
  }, [])

  if (!editor) return null

  return (
    <div
      className="web-editor-toolbar fixed z-20 flex h-[44px] items-center gap-1 overflow-x-auto rounded-full border border-border bg-card shadow-md px-3"
      style={{
        bottom: `max(calc(0.75rem + 22px), calc(env(safe-area-inset-bottom, 0px) + 5px))`,
        left: `max(21px, calc((100vw - 42rem) / 2 + 5px))`,
        right: `max(calc(21px + 44px + 12px), calc((100vw - 42rem) / 2 + 5px + 44px + 12px))`,
        ...(bottomOffset ? { marginBottom: bottomOffset } : {}),
      }}
    >
      {actions.map(action => {
        const active = action.isActive?.(editor)
        const IconComp = action.icon
        return (
          <button
            key={action.label}
            type="button"
            title={action.label}
            onPointerDown={e => {
              e.preventDefault()
              action.command(editor)
            }}
            className={`flex-shrink-0 rounded-md p-2 ${
              active
                ? "bg-accent text-accent-foreground"
                : "text-muted-foreground hover:bg-muted hover:text-foreground"
            }`}
          >
            <IconComp size={20} weight={active ? "bold" : "regular"} />
          </button>
        )
      })}
    </div>
  )
}

